require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$errors=[];$hospitals=db()->query("SELECT id,name,district FROM hospitals WHERE status='active' ORDER BY name")->fetchAll();
if(request_method('POST')){Csrf::verify();$action=$_POST['action']??'';if($action==='create_staff'){$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=normalize_sl_phone($_POST['phone']??'');$hid=(int)($_POST['hospital_id']??0);$org=isset($_POST['organ_access'])?1:0;$valid=false;foreach($hospitals as $h)if((int)$h['id']===$hid)$valid=true;if(strlen($name)<3)$errors[]='Enter staff name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!$phone)$errors[]='Enter a valid mobile number.';if(!$valid)$errors[]='Select a hospital.';if(!$errors){try{$temp=random_token(16);db()->prepare("INSERT INTO users(role,hospital_id,full_name,email,phone,password_hash,status,email_verified_at,phone_verified_at,mfa_enabled,organ_access_enabled) VALUES('hospital',?,?,?,?,?,'pending_password',NOW(),NOW(),1,?)")->execute([$hid,$name,$email,$phone,password_hash($temp,PASSWORD_DEFAULT),$org]);$uid=(int)db()->lastInsertId();$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([$uid]);$u=$s->fetch();$dev=(new VerificationService())->createPasswordReset($u,'hospital_invite');if($dev)$_SESSION['dev_staff_invite_url']=$dev;audit('hospital_staff_created','user',$uid,['hospital_id'=>$hid,'organ_access'=>$org]);flash('success','Hospital staff account created.');redirect('admin/users.php');}catch(Throwable $e){$errors[]='Staff account could not be created: '.$e->getMessage();}}}elseif($action==='update_user'){$uid=(int)($_POST['user_id']??0);$status=$_POST['status']??'';$mfa=isset($_POST['mfa_enabled'])?1:0;$organ=isset($_POST['organ_access_enabled'])?1:0;if(in_array($status,['active','suspended','pending_password','pending_verification'],true)){db()->prepare('UPDATE users SET status=?,mfa_enabled=?,organ_access_enabled=CASE WHEN role=\'hospital\' THEN ? ELSE 0 END WHERE id=?')->execute([$status,$mfa,$organ,$uid]);audit('user_access_updated','user',$uid,['status'=>$status,'mfa'=>$mfa,'organ'=>$organ]);flash('success','User access updated.');redirect('admin/users.php');}}}
$rows=db()->query("SELECT u.*,h.name hospital_name FROM users u LEFT JOIN hospitals h ON h.id=u.hospital_id ORDER BY u.created_at DESC LIMIT 500")->fetchAll();$pageTitle='Manage Users';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>User & access management</h1></div></div><?=admin_nav()?><?php if(!empty($_SESSION['dev_staff_invite_url'])):?><div class="flash success"><strong>Local development staff setup link:</strong> <a href="<?=e((string)$_SESSION['dev_staff_invite_url'])?>">Open password setup</a></div><?php unset($_SESSION['dev_staff_invite_url']);endif;?><div class="grid-2"><div class="card"><h2>Create hospital staff account</h2><?php if($errors):?><div class="error-list"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="create_staff"><div class="field"><label>Hospital</label><select name="hospital_id" required><option value="">Select</option><?php foreach($hospitals as $h):?><option value="<?=e((string)$h['id'])?>"><?=e($h['name'])?> · <?=e($h['district'])?></option><?php endforeach;?></select></div><div class="field"><label>Staff name</label><input name="full_name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone" placeholder="0771234567" required></div><label class="check-row"><input type="checkbox" name="organ_access"><span>Grant restricted organ-interest access</span></label><button class="btn">Create Staff Account</button></form></div><div class="card"><h2>Access policy</h2><p>Hospital staff use MFA by default. Organ-interest records require the separate permission shown here; normal hospital access alone is not enough.</p><div class="danger-note">Suspend an account immediately if access should no longer be allowed. Suspended users cannot sign in.</div></div></div><h2 class="mt-2">Registered users</h2><div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Role / Hospital</th><th>Status</th><th>MFA</th><th>Organ access</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><br><span class="small"><?=e($r['email'])?></span></td><td><?=e(ucfirst($r['role']))?><?php if($r['hospital_name']):?><br><span class="small"><?=e($r['hospital_name'])?></span><?php endif;?></td><td><?=e($r['status'])?></td><td><?=$r['mfa_enabled']?'Yes':'No'?></td><td><?=$r['organ_access_enabled']?'Granted':'—'?></td><td><form method="post" class="mini-actions"><?=Csrf::field()?><input type="hidden" name="action" value="update_user"><input type="hidden" name="user_id" value="<?=e((string)$r['id'])?>"><select name="status"><option value="active" <?=$r['status']==='active'?'selected':''?>>Active</option><option value="suspended" <?=$r['status']==='suspended'?'selected':''?>>Suspended</option><?php if($r['status']==='pending_password'):?><option value="pending_password" selected>Pending password</option><?php endif;?><?php if($r['status']==='pending_verification'):?><option value="pending_verification" selected>Pending verification</option><?php endif;?></select><label class="small"><input type="checkbox" name="mfa_enabled" <?=$r['mfa_enabled']?'checked':''?>> MFA</label><?php if($r['role']==='hospital'):?><label class="small"><input type="checkbox" name="organ_access_enabled" <?=$r['organ_access_enabled']?'checked':''?>> Organ</label><?php endif;?><button class="btn btn-sm">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section>
